-- ===== sekwencje =====
SELECT setval(pg_get_serial_sequence('customers', 'customer_id'), COALESCE((SELECT MAX(customer_id) FROM customers), 1), (SELECT COUNT(*) > 0 FROM customers));
SELECT setval(pg_get_serial_sequence('equipment', 'equipment_id'), COALESCE((SELECT MAX(equipment_id) FROM equipment), 1), (SELECT COUNT(*) > 0 FROM equipment));
SELECT setval(pg_get_serial_sequence('rentals', 'rental_id'), COALESCE((SELECT MAX(rental_id) FROM rentals), 1), (SELECT COUNT(*) > 0 FROM rentals));
SELECT setval(pg_get_serial_sequence('rental_items', 'rental_item_id'), COALESCE((SELECT MAX(rental_item_id) FROM rental_items), 1), (SELECT COUNT(*) > 0 FROM rental_items));
SELECT setval(pg_get_serial_sequence('payments', 'payment_id'), COALESCE((SELECT MAX(payment_id) FROM payments), 1), (SELECT COUNT(*) > 0 FROM payments));

COMMIT;
